konsole_tabs:
/* Generated by ~/.config/plasma-rice/rice.py from the wallpaper palette. Do not edit. */
QTabBar { background: rgba(4,18,23, 217); }
QTabBar::tab {
    background: transparent; color: #62808b;
    border: 1px solid transparent; border-radius: 10px;
    padding: 4px 12px; margin: 8px 2px 2px 2px;
    min-width: 7em; max-width: 22em;
}
QTabBar::tab:first { margin-left: 12px; }
QTabBar::tab:hover:!selected { background: rgba(209,229,237, 20); color: #9cb6bf; }
QTabBar::tab:selected {
    background: rgba(159,205,148, 41); color: #d1e5ed;
    border-color: rgba(159,205,148, 82);
}

zen:
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py from the wallpaper palette. Do not edit. */
:root, :host(:is(.anonymous-content-host, notification-message)) {
  --zen-primary-color: #9fcd94 !important;
  --zen-branding-dark: #041217 !important;
  --zen-colors-primary: color-mix(in srgb, #9fcd94 22%, #07161b) !important;
  --zen-colors-secondary: color-mix(in srgb, #9fcd94 32%, #07161b) !important;
  --zen-colors-tertiary: #010b10 !important;
  --zen-colors-hover-bg: color-mix(in srgb, #9fcd94 14%, #0a1a1f) !important;
  --zen-colors-primary-foreground: #d1e5ed !important;
  --zen-colors-border: rgba(39,66,75, 0.55) !important;
  --zen-colors-border-contrast: rgba(39,66,75, 0.3) !important;
  --zen-colors-input-bg: #0a1a1f !important;
  --zen-input-border-color: #27424b !important;
  --zen-dialog-background: #07161b !important;
  --zen-urlbar-background: #0a1a1f !important;
  --zen-main-browser-background: linear-gradient(135deg, rgba(33,51,29, 0.72) 0%, rgba(1,11,16, 0.84) 52%, rgba(68,36,23, 0.68) 100%) !important;
  --zen-main-browser-background-toolbar: linear-gradient(135deg, rgba(33,51,29, 0.72) 0%, rgba(1,11,16, 0.84) 52%, rgba(68,36,23, 0.68) 100%) !important;
  --toolbox-textcolor: #d1e5ed !important;
  --toolbar-field-color: #d1e5ed !important;
  --arrowpanel-background: #0a1a1f !important;
  --arrowpanel-color: #d1e5ed !important;
  --arrowpanel-border-color: rgba(39,66,75, 0.6) !important;
  --panel-separator-color: rgba(39,66,75, 0.6) !important;
  --focus-outline-color: #9fcd94 !important;
  --zen-sidebar-themed-icon-fill: #9cb6bf !important;
}

/* Zen paints the workspace gradient on these layers and sets its variables inline on them,
   so override the layers themselves (::before is the cross-fade target while switching spaces) */
.zen-browser-generic-background::after,
.zen-browser-generic-background::before {
  background: linear-gradient(135deg, rgba(33,51,29, 0.72) 0%, rgba(1,11,16, 0.84) 52%, rgba(68,36,23, 0.68) 100%) !important;
}

/* selected tab: a soft accent wash with a hairline, instead of plain white */
.tabbrowser-tab:is([selected], [multiselected]) .tab-background {
  background-color: rgba(159,205,148, 0.16) !important;
  box-shadow: inset 0 0 0 1px rgba(159,205,148, 0.32) !important;
}
.tabbrowser-tab:not([selected]):hover .tab-background {
  background-color: rgba(209,229,237, 0.07) !important;
}

/* command bar / url bar popup */
#urlbar[breakout-extend] > .urlbar-background,
#urlbar[breakout-extend] #urlbar-background {
  background-color: #0a1a1f !important;
  border: 1px solid rgba(39,66,75, 0.7) !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45) !important;
}
.urlbarView-row[selected] {
  background-color: rgba(159,205,148, 0.18) !important;
}

/* menus and popups */
menupopup, panel {
  --panel-background: #0a1a1f !important;
  --panel-color: #d1e5ed !important;
  --panel-border-color: rgba(39,66,75, 0.6) !important;
}
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py. Do not edit. */
:root {
  scrollbar-color: rgba(79,107,117, 0.7) transparent;
}
@-moz-document url("about:blank"), url("about:newtab"), url("about:home"), url("about:privatebrowsing") {
  html, body { background-color: #041217 !important; }
}
